CREATE TABLE IF NOT EXISTS bm_users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(320) NOT NULL UNIQUE,username VARCHAR(64) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,mailbox_password_enc TEXT NOT NULL,display_name VARCHAR(120) DEFAULT '',locale VARCHAR(10) NOT NULL DEFAULT 'fa',theme VARCHAR(20) NOT NULL DEFAULT 'dark',quota_mb INT UNSIGNED NOT NULL DEFAULT 1024,is_admin TINYINT(1) NOT NULL DEFAULT 0,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bm_oauth_clients (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,client_id VARCHAR(80) NOT NULL UNIQUE,client_secret_hash VARCHAR(255) NOT NULL,name VARCHAR(120) NOT NULL,redirect_uris TEXT NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES bm_users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bm_oauth_codes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code_hash CHAR(64) NOT NULL UNIQUE,client_id VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,redirect_uri TEXT NOT NULL,scope VARCHAR(255) NOT NULL DEFAULT 'openid profile email',expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bm_oauth_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,client_id VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,scope VARCHAR(255) NOT NULL DEFAULT 'openid profile email',expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id),INDEX(expires_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS bm_refresh_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,token_hash CHAR(64) NOT NULL UNIQUE,client_id VARCHAR(80) NOT NULL,user_id BIGINT UNSIGNED NOT NULL,scope VARCHAR(255) NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
